--!strict
local Players=game:GetService("Players");local Profiles=require(script.Parent.Services.PlayerProfileService);local Rewards=require(script.Parent.Services.RewardService);local Leaderboards=require(script.Parent.Services.GlobalLeaderboardService);local Events=require(script.Parent.Services.GameplayEventService);local Tower=require(script.Parent.Services.TowerService);local Lobby=require(script.Parent.Services.LobbyService);local Race=require(script.Parent.Services.RaceService);local Registry=require(script.Parent.Services.ConnectionRegistry);local remotes=require(script.Parent.Services.RemoteService).Ensure();local world=workspace:WaitForChild("PartyObbyWorld",10);local maps=world and world:WaitForChild("TowerMaps",10)
local function player(hit:BasePart):Player?local n:Instance?=hit;while n and n~=workspace do if n:IsA("Model")and n:FindFirstChildOfClass("Humanoid")then return Players:GetPlayerFromCharacter(n)end;n=n.Parent end;return nil end
local function bind(map:Folder)
	local id=map.Name;local floors=map:FindFirstChild("Floors");if not floors then return end;local floorCount=#floors:GetChildren();for _,floor in floors:GetChildren()do if floor:IsA("BasePart")then Registry.Register(floor.Touched:Connect(function(hit)local p=player(hit);local s=p and Tower.Session(p);local index=floor:GetAttribute("TowerFloor");if p and s and s.mapId==id and s.active and typeof(index)=="number"and index==s.floor+1 then s.floor=index;s.lastCFrame=floor.CFrame;local profile=Profiles.GetProfile(p);if profile then profile.Tower.HighestFloorByTower[id]=math.max(profile.Tower.HighestFloorByTower[id]or 0,index);Profiles.MarkDirty(p)end;remotes.TowerProgressUpdated:FireClient(p,{floor=index,total=s.floorCount,best=profile and((profile.Tower.BestTowerTimes[id]or 0)/1000)or 0,towerId=id});print(string.format("[Tower] %s reached %s floor %d",p.Name,id,index))end end),"TowerMap:"..id,"Touched")end end
	local finish=map:FindFirstChild("TowerFinish");if finish and finish:IsA("BasePart")then Registry.Register(finish.Touched:Connect(function(hit)local p=player(hit);local s=p and Tower.Session(p);if not p or not s or s.mapId~=id or s.floor<floorCount or not s.active then return end;s.active=false;local elapsed=os.clock()-s.started;local ms=math.floor(elapsed*1000);local profile=Profiles.GetProfile(p);if not profile then return end;local old=profile.Tower.BestTowerTimes[id]or 0;local first=old==0;local personalBest=first or ms<old;if personalBest then profile.Tower.BestTowerTimes[id]=ms;if id=="Tower01"then Leaderboards.Update(p,"Tower",ms)end end;profile.Tower.TowersCompleted+=1;Profiles.MarkDirty(p);local coins=Rewards.Tower(p,s.runId,first,personalBest);Events.Event:Fire(p,"TowerComplete",1);if s.falls==0 then Events.Event:Fire(p,"TowerNoFalls",1)end;if id=="Tower02"then Events.Event:Fire(p,"Tower02Complete",1)end;remotes.TowerProgressUpdated:FireClient(p,{completed=true,time=elapsed,best=profile.Tower.BestTowerTimes[id]/1000,coinsEarned=coins,towerId=id});print(string.format("[Tower] %s completed %s in %.1f seconds",p.Name,id,elapsed));Tower.Leave(p);task.delay(10,function()if p.Parent==Players then Lobby.Return(p)end end)end),"TowerMap:"..id,"Touched")end
	local kill=map:FindFirstChild("KillFloor");if kill and kill:IsA("BasePart")then Registry.Register(kill.Touched:Connect(function(hit)local p=player(hit);local s=p and Tower.Session(p);if p and s and s.mapId==id then s.falls+=1;Profiles.IncrementValue(p,"Tower.TotalFalls",1);Race.Teleport(p,s.lastCFrame,8)end end),"TowerMap:"..id,"Touched")end
end
if maps then for _,map in maps:GetChildren()do if map:IsA("Folder")then bind(map)end end end
